export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

export function charsetIndex(character) {
  return CHARSET.indexOf(character);
}

const GENERATORS = [
  0x3b6a57b2,
  0x26508e6d,
  0x1ea119fa,
  0x3d4233dd,
  0x2a1462b3,
];

export function polymod(values) {
  let checksum = 1;

  for (const value of values) {
    const top = checksum >>> 25;
    checksum = ((checksum & 0x1ffffff) << 5) ^ value;

    for (let index = 0; index < GENERATORS.length; index += 1) {
      if (((top >>> index) & 1) !== 0) {
        checksum ^= GENERATORS[index];
      }
    }
  }

  return checksum >>> 0;
}

export function expandHrp(hrp) {
  const expanded = [];

  for (let index = 0; index < hrp.length; index += 1) {
    expanded.push(hrp.charCodeAt(index) >>> 5);
  }

  expanded.push(0);

  for (let index = 0; index < hrp.length; index += 1) {
    expanded.push(hrp.charCodeAt(index) & 31);
  }

  return expanded;
}

export function createChecksum(hrp, data) {
  const values = [...expandHrp(hrp), ...data, 0, 0, 0, 0, 0, 0];
  const value = polymod(values) ^ 1;
  const checksum = [];

  for (let index = 0; index < 6; index += 1) {
    checksum.push((value >>> (5 * (5 - index))) & 31);
  }

  return checksum;
}

export function verifyChecksum(hrp, data) {
  return polymod([...expandHrp(hrp), ...data]) === 1;
}

import { CHARSET, charsetIndex } from './charset.mjs';
import { createChecksum, verifyChecksum } from './checksum.mjs';

export function encodeBech32(hrp, data) {
  for (const value of data) {
    if (!Number.isInteger(value) || value < 0 || value > 31) {
      return null;
    }
  }

  const combined = [...data, ...createChecksum(hrp, data)];
  let encoded = `${hrp}1`;

  for (const value of combined) {
    encoded += CHARSET[value];
  }

  return encoded;
}

export function decodeBech32(address) {
  if (address.length > 90) {
    return null;
  }

  let hasLowercase = false;
  let hasUppercase = false;

  for (let index = 0; index < address.length; index += 1) {
    const code = address.charCodeAt(index);
    if (code < 33 || code > 126) {
      return null;
    }
    if (code >= 97 && code <= 122) {
      hasLowercase = true;
    }
    if (code >= 65 && code <= 90) {
      hasUppercase = true;
    }
  }

  if (hasLowercase && hasUppercase) {
    return null;
  }

  const normalized = address.toLowerCase();
  const separator = normalized.lastIndexOf('1');

  if (separator < 1 || separator + 7 > normalized.length) {
    return null;
  }

  const hrp = normalized.slice(0, separator);
  const data = [];

  for (let index = separator + 1; index < normalized.length; index += 1) {
    const value = charsetIndex(normalized[index]);
    if (value === -1) {
      return null;
    }
    data.push(value);
  }

  if (!verifyChecksum(hrp, data)) {
    return null;
  }

  return {
    hrp,
    data: data.slice(0, -6),
  };
}

import { decodeBech32, encodeBech32 } from './bech32.mjs';

export function convertBits(data, fromBits, toBits, pad) {
  let accumulator = 0;
  let bits = 0;
  const result = [];
  const maximumValue = (1 << toBits) - 1;
  const maximumAccumulator = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (!Number.isInteger(value) || value < 0 || value >= (1 << fromBits)) {
      return null;
    }

    accumulator = ((accumulator << fromBits) | value) & maximumAccumulator;
    bits += fromBits;

    while (bits >= toBits) {
      bits -= toBits;
      result.push((accumulator >>> bits) & maximumValue);
    }
  }

  if (pad) {
    if (bits > 0) {
      result.push((accumulator << (toBits - bits)) & maximumValue);
    }
  } else if (bits >= fromBits || ((accumulator << (toBits - bits)) & maximumValue) !== 0) {
    return null;
  }

  return result;
}

export function decodeSegwitAddress(expectedHrp, address) {
  const decoded = decodeBech32(address);

  if (decoded === null || decoded.hrp !== expectedHrp || decoded.data.length === 0) {
    return null;
  }

  const version = decoded.data[0];
  const program = convertBits(decoded.data.slice(1), 5, 8, false);

  if (program === null || program.length < 2 || program.length > 40) {
    return null;
  }

  if (version > 16) {
    return null;
  }

  if (version === 0 && program.length !== 20 && program.length !== 32) {
    return null;
  }

  return { version, program };
}

export function encodeSegwitAddress(hrp, version, program) {
  const converted = convertBits(program, 8, 5, true);

  if (converted === null) {
    return null;
  }

  const address = encodeBech32(hrp, [version, ...converted]);

  if (address === null || decodeSegwitAddress(hrp, address) === null) {
    return null;
  }

  return address;
}

const OPTION_NAMES = new Set(['a', 'b', 'c']);

export class ArgumentError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentError';
  }
}

export class HelpRequested extends Error {
  constructor() {
    super('help requested');
    this.name = 'HelpRequested';
  }
}

function parseInteger(value, optionName) {
  const text = String(value).trim();

  if (!/^[+-]?(?:\d+(?:_\d+)*)$/.test(text)) {
    throw new ArgumentError(`argument --${optionName}: invalid int value: '${value}'`);
  }

  return Number.parseInt(text.replaceAll('_', ''), 10);
}

function isOptionLike(value, optionName) {
  if (!value.startsWith('-')) {
    return false;
  }

  if (optionName === 'b' && /^-\d/.test(value)) {
    return false;
  }

  return true;
}

export function parseCommandLine(argv) {
  const values = {};

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new HelpRequested();
    }

    if (!token.startsWith('--')) {
      throw new ArgumentError(`unrecognized arguments: ${token}`);
    }

    const equalsIndex = token.indexOf('=');
    const name = equalsIndex === -1 ? token.slice(2) : token.slice(2, equalsIndex);

    if (!OPTION_NAMES.has(name)) {
      throw new ArgumentError(`unrecognized arguments: ${token}`);
    }

    let value;
    if (equalsIndex !== -1) {
      value = token.slice(equalsIndex + 1);
    } else {
      if (index + 1 >= argv.length || isOptionLike(argv[index + 1], name)) {
        throw new ArgumentError(`argument --${name}: expected one argument`);
      }
      index += 1;
      value = argv[index];
    }

    values[name] = name === 'b' ? parseInteger(value, name) : value;
  }

  const missing = [];
  for (const name of ['a', 'b', 'c']) {
    if (!(name in values)) {
      missing.push(`--${name}`);
    }
  }

  if (missing.length > 0) {
    throw new ArgumentError(`the following arguments are required: ${missing.join(', ')}`);
  }

  return values;
}

export function usage(programName) {
  return `usage: ${programName} [-h] --a A --b B --c C`;
}

export function helpText(programName) {
  return `${usage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n  --c C`;
}

export function parseWitnessProgram(text) {
  return String(text).split(',').map((part) => {
    const value = part.trim();

    if (!/^[+-]?(?:\d+(?:_\d+)*)$/.test(value)) {
      throw new Error(`invalid literal for int() with base 10: '${part}'`);
    }

    return Number.parseInt(value.replaceAll('_', ''), 10);
  });
}

import {
  ArgumentError,
  HelpRequested,
  helpText,
  parseCommandLine,
  parseWitnessProgram,
  usage,
} from './lib/arguments.mjs';
import { encodeSegwitAddress } from './lib/segwit.mjs';

function programName() {
  const scriptPath = process.argv[1] || 'test4.mjs';
  return scriptPath.split('/').pop() || scriptPath;
}

function main() {
  let args;

  try {
    args = parseCommandLine(process.argv.slice(2));
  } catch (error) {
    if (error instanceof HelpRequested) {
      console.log(helpText(programName()));
      return 0;
    }

    if (error instanceof ArgumentError) {
      console.error(usage(programName()));
      console.error(`${programName()}: error: ${error.message}`);
      return 2;
    }

    throw error;
  }

  const witnessProgram = parseWitnessProgram(args.c);
  const result = encodeSegwitAddress(args.a, args.b, witnessProgram);
  console.log(result === null ? 'None' : result);
  return 0;
}

process.exitCode = main();
